/* xx_vhddynamic_extractor.c - search raw data for VHDDynamic.
 *
 * Scans for:
 *   63 6F 6E 65 63 74 69 78 at +0  ("conectix")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the vhddynamic reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/vhddynamic/xx_vhddynamic.h"

static const uint8_t k_anchor0[] = { 0x63, 0x6F, 0x6E, 0x65, 0x63, 0x74, 0x69, 0x78 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_VHDDYNAMIC };

static Abstractformat *xx_vhddynamic_search_open(xx_io_device *window) {
    xx_vhddynamic *reader = xx_vhddynamic_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_vhddynamic_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_vhddynamic_free((xx_vhddynamic *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_vhddynamic_search_open, xx_vhddynamic_search_close
};

static xx_format_search_state *xx_vhddynamic_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_vhddynamic_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_vhddynamic_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_vhddynamic_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_vhddynamic_extractor = {
    xx_vhddynamic_create_format_search,
    xx_vhddynamic_get_current_format_info,
    xx_vhddynamic_format_search_find_next,
    xx_vhddynamic_free_format_search
};
